using Bunit;
using Habitica.Domain.Workspace;
using Habitica.WebApp.Components;
using Habitica.WebApp.State;
using Microsoft.Extensions.DependencyInjection;
using MudBlazor.Services;
namespace Habitica.WebApp.Tests.Workspace;
public sealed class TaskTypeConversionPanelTests:BunitContext
{
    private async Task<(TodoOrganizationFixture F,CompanionTask Source)> Setup(CompanionTaskKind kind=CompanionTaskKind.Todo,bool cloud=true,int extra=0,bool longName=false)
    {
        JSInterop.Mode=JSRuntimeMode.Loose;Services.AddMudServices();var now=DateTimeOffset.Parse("2026-11-01T00:00:00Z");var source=new CompanionTask(Guid.NewGuid(),1,longName?new string('W',180)+" retained source":"Retained source",kind,CompanionTaskState.Active,CompanionPriority.High,now,now,Notes:"Exact private notes",IsArchived:true);
        var f=new TodoOrganizationFixture();await f.Load(cloud,new(){Id=Guid.NewGuid(),Revision=10,Tasks=Enumerable.Range(0,extra).Select(i=>source with{Id=Guid.NewGuid(),Text="Other source "+i}).Append(source).ToArray(),Projections=[new(Guid.NewGuid(),2,source.Id,ProjectionState.Linked,Guid.NewGuid().ToString("D"))]});
        Services.AddSingleton<IAppSessionController>(f.Task.Session);Services.AddSingleton(f.Todo);Services.AddSingleton<TodoTaskDraftStore>();Services.AddSingleton(new WorkspaceConversionController(f.Task.Session,f.Task.Client));return(f,source);
    }
    private static void Save(string name,string markup,string state)=>Qualification.PageLayoutEvidence.Save(name,markup,"/todo/convert",state,["form","actions","confirmation","disabled-controls","error","navigation"],nameof(TaskTypeConversionPanelTests));
    private IRenderedComponent<TaskTypeCopyPanel> Choose(CompanionTask task){var cut=Render<TaskTypeCopyPanel>();cut.Find($"[data-testid=type-copy-source-{task.Id:D}]").Click();return cut;}
    private static void Prepare(IRenderedComponent<TaskTypeCopyPanel> cut,CompanionTaskKind kind)
    {
        cut.Find("[data-testid=type-copy-kind]").Change(kind.ToString());if(kind==CompanionTaskKind.Daily)cut.Find("[data-testid=type-copy-start]").Change("2026-11-03");cut.Find("[data-testid=type-copy-prepare]").Click();
    }
    [Fact]public async Task Copy_browser_fixture_and_owning_reviews_preserve_complete_exact_sources()
    {
        var(f,old)=await Setup(cloud:false);using var owned=f;var now=DateTimeOffset.Parse("2026-11-01T00:00:00Z");var category=Guid.NewGuid();var project=Guid.NewGuid();var section=Guid.NewGuid();var label=Guid.NewGuid();
        CompanionTask Make(string name)=>new(Guid.NewGuid(),1,name,CompanionTaskKind.Todo,CompanionTaskState.Active,CompanionPriority.Low,now,now);
        var parent=Make("Retained parent");var dependency=Make("Retained dependency");var minimal=Make("Minimal exact copy source");var populated=Make("Populated exact copy source") with{Notes="Exact private source notes",CategoryId=category,ProjectId=project,SectionId=section,LabelIds=[label],ParentTaskId=parent.Id,DependsOn=[dependency.Id],PlannedDate=new(2026,11,1),Deadline=new(2026,11,3),ReviewAfterUtc=now,StaleSinceUtc=now,ExecutionStage=TodoExecutionStage.Inbox};
        var document=new WorkspaceDocument{Id=f.Todo.Snapshot!.Document.Id,Revision=10,Tasks=[minimal,populated,parent,dependency],Categories=[new(category,1,"Exact category")],Projects=[new(project,1,"Exact project",category)],Sections=[new(section,1,"Exact section",project)],Labels=[new(label,1,"Exact label")]};Assert.Empty(WorkspaceRules.Validate(document));var state=new WorkspaceJournalSnapshot(document,10,[],[]);f.Task.Js.Rows[(WorkspaceTaskFixture.User,document.Id.ToString("D"))]=WorkspaceJournalJson.Serialize(state);await f.Todo.LoadSelectedAsync();
        var output=Environment.GetEnvironmentVariable("HABITICA_BROWSER_EVIDENCE");if(!string.IsNullOrEmpty(output)){Directory.CreateDirectory(output);await File.WriteAllTextAsync(Path.Combine(output,"copy-browser-source.json"),WorkspaceJournalJson.Serialize(state));}
        var before=WorkspaceJournalJson.Serialize(f.Todo.Snapshot!);var cut=Choose(minimal);Prepare(cut,CompanionTaskKind.Habit);Assert.Equal(minimal.Id,f.Task.Controller.Preview!.TypeCopyPreview!.Source!.Id);Save("copy-unset-minimal-owner",cut.Markup,"actual-owner-null-values-and-original-confirmation");cut.FindAll("button").Single(b=>b.TextContent=="Cancel unaccepted review").Click();cut.Find($"[data-testid='type-copy-source-{populated.Id:D}']").Click();Prepare(cut,CompanionTaskKind.Daily);Assert.Equal(TodoExecutionStage.Inbox,f.Task.Controller.Preview!.TypeCopyPreview!.Source!.ExecutionStage);Assert.Equal(project,f.Task.Controller.Preview.TypeCopyPreview.Target!.ProjectId);Save("copy-unset-populated-owner",cut.Markup,"actual-owner-populated-fields-and-original-confirmation");Assert.Equal(before,WorkspaceJournalJson.Serialize(f.Todo.Snapshot!));Assert.Empty(f.Task.Client.AcceptedIds);
    }

    [Fact]public void Copy_review_names_unset_values_and_preserves_zero_valued_enums()
    {
        var now=DateTimeOffset.Parse("2026-11-01T00:00:00Z");var source=new CompanionTask(Guid.NewGuid(),3,"Minimal source",CompanionTaskKind.Todo,CompanionTaskState.Active,CompanionPriority.Low,now,now);var document=new WorkspaceDocument{Id=Guid.NewGuid(),Revision=3,Tasks=[source]};var review=WorkspaceTaskTypeCopyPolicy.Review(document,new(source.Id,3,CompanionTaskKind.Habit,false),Guid.NewGuid(),now);Assert.True(review.Ready);var before=System.Text.Json.JsonSerializer.Serialize(review);
        var cut=Render<TaskTypeCopyReview>(p=>p.Add(c=>c.Review,review));var original=cut.Find("[data-testid='type-copy-source-summary']");var target=cut.Find("[data-testid='type-copy-target-summary']");
        foreach(var label in new[]{"Schedule","Planned date","Deadline","Review cue","Stale since","Stage","Parent","Category","Project","Section"})Assert.Equal("Not set",Field(original,label));
        Assert.Equal("None",Field(original,"Dependencies"));Assert.Equal("None",Field(original,"Labels"));Assert.Equal("Not set",Field(target,"Category"));Assert.Equal("None",Field(target,"Labels"));Assert.Contains("Todo",original.TextContent);Assert.Contains("Active",original.TextContent);Assert.Contains("Low",target.TextContent);Assert.Contains(source.Id.ToString("D"),original.TextContent);Assert.Contains(review.Target!.Id.ToString("D"),target.TextContent);Assert.Equal(before,System.Text.Json.JsonSerializer.Serialize(review));Save("copy-unset-minimal",cut.Markup,"explicit-null-and-empty-with-zero-enums");
    }
    [Fact]public void Copy_review_preserves_populated_metadata_dates_and_Inbox_stage()
    {
        var now=DateTimeOffset.Parse("2026-11-01T00:00:00Z");var category=Guid.NewGuid();var project=Guid.NewGuid();var section=Guid.NewGuid();var label=Guid.NewGuid();var parent=Guid.NewGuid();var dependency=Guid.NewGuid();
        var source=new CompanionTask(Guid.NewGuid(),3,"Populated source",CompanionTaskKind.Todo,CompanionTaskState.Active,CompanionPriority.Low,now,now,Notes:"Exact <private> notes",CategoryId:category,ProjectId:project,SectionId:section,ParentTaskId:parent,LabelIds:[label],DependsOn:[dependency],PlannedDate:new(2026,11,1),Deadline:new(2026,11,3),ReviewAfterUtc:now,StaleSinceUtc:now,ExecutionStage:TodoExecutionStage.Inbox);
        var target=source with{Id=Guid.NewGuid(),Kind=CompanionTaskKind.Habit,ParentTaskId=null,DependsOn=[],PlannedDate=null,Deadline=null,ReviewAfterUtc=null,StaleSinceUtc=null,ExecutionStage=null};var review=new WorkspaceTaskTypeCopyReview(source,target,["Name","Notes","Native urgency","Category/project/section/labels"],["Todo stage/parent/dependencies/goal membership"],null);var before=System.Text.Json.JsonSerializer.Serialize(review);var cut=Render<TaskTypeCopyReview>(p=>p.Add(c=>c.Review,review));var original=cut.Find("[data-testid='type-copy-source-summary']");var copied=cut.Find("[data-testid='type-copy-target-summary']");
        Assert.Equal("Inbox",Field(original,"Stage"));Assert.Equal("2026-11-01",Field(original,"Planned date"));Assert.Equal("2026-11-03",Field(original,"Deadline"));Assert.Equal(now.ToString("O",System.Globalization.CultureInfo.InvariantCulture),Field(original,"Review cue"));Assert.Equal(parent.ToString("D"),Field(original,"Parent"));Assert.Equal(dependency.ToString("D"),Field(original,"Dependencies"));
        foreach(var pair in new[]{("Category",category),("Project",project),("Section",section),("Labels",label)}){Assert.Equal(pair.Item2.ToString("D"),Field(original,pair.Item1));Assert.Equal(pair.Item2.ToString("D"),Field(copied,pair.Item1));}
        Assert.Contains("Exact <private> notes",copied.TextContent);Assert.DoesNotContain("<private>",cut.Markup);Assert.Contains("No Habitica task, tag, score or Cron",cut.Markup);Assert.Equal(before,System.Text.Json.JsonSerializer.Serialize(review));Save("copy-unset-populated",cut.Markup,"exact-populated-metadata-and-zero-Inbox-stage");
    }
    private static string Field(AngleSharp.Dom.IElement summary,string label)=>summary.QuerySelectorAll("dt").Single(el=>el.TextContent==label).NextElementSibling!.TextContent;

    [Theory][InlineData(CompanionTaskKind.Todo,CompanionTaskKind.Daily)][InlineData(CompanionTaskKind.Todo,CompanionTaskKind.Habit)][InlineData(CompanionTaskKind.Daily,CompanionTaskKind.Todo)][InlineData(CompanionTaskKind.Daily,CompanionTaskKind.Habit)][InlineData(CompanionTaskKind.Habit,CompanionTaskKind.Todo)][InlineData(CompanionTaskKind.Habit,CompanionTaskKind.Daily)]
    public async Task Native_copy_reviews_every_loss_and_requires_explicit_acceptance_for_all_distinct_kind_pairs(CompanionTaskKind from,CompanionTaskKind to)
    {
        var(f,source)=await Setup(from);using var owned=f;var cut=Choose(source);Assert.True(cut.Find("[data-testid=type-copy-prepare]").HasAttribute("disabled"));Save("type-copy-editor",cut.Markup,"exact-archived-linked-source-selection");Prepare(cut,to);cut.WaitForAssertion(()=>Assert.NotNull(f.Task.Controller.Preview));var preview=f.Task.Controller.Preview!;Assert.Equal(to,preview.TypeCopyPreview!.Target!.Kind);Assert.False(preview.MayAffectHabitica);Assert.True(cut.Find("[data-testid=type-copy-confirm]").HasAttribute("disabled"));Assert.Contains(source.Notes!,cut.Markup);Assert.Contains("Todo stage/parent/dependencies/goal membership",cut.Markup);Assert.Contains("No Habitica task, tag, score or Cron",cut.Markup);Save("type-copy-review-"+to.ToString().ToLowerInvariant(),cut.Markup,"complete-before-after-reset-review");
        if(to==CompanionTaskKind.Habit&&from==CompanionTaskKind.Todo){var sync=Render<TodoTaskPanel>(p=>p.Add(x=>x.ShowCapture,false).Add(x=>x.ShowTaskList,false));Assert.Contains("Exact new ID",sync.Markup);Qualification.PageLayoutEvidence.Save("type-copy-sync-review",sync.Markup,"/todo/sync","original-type-copy-full-field-review",["form","actions","confirmation","disabled-controls","error","navigation"],nameof(TaskTypeConversionPanelTests));}
        cut.Find("[data-testid=type-copy-ack]").Change(true);cut.Find("[data-testid=type-copy-confirm]").Click();cut.WaitForAssertion(()=>Assert.NotNull(f.Task.Controller.LastReceipt));Assert.Single(f.Task.Client.AcceptedIds);Assert.Equal(source,f.Task.Client.State.Document.Tasks[0]);Assert.Single(f.Task.Client.State.Document.Projections);Assert.Empty(f.Task.Client.State.Commands.Single().Effects);Assert.Equal(2,f.Task.Client.State.Document.Tasks.Count);Assert.Contains("source",cut.Find("[data-testid=type-copy-receipt]").TextContent);Save("type-copy-saved",cut.Markup,"original-receipt-with-source-retained");
    }
    [Fact]public async Task Missing_Daily_start_and_invalid_timezone_never_prepare_a_copy()
    {
        var(f,source)=await Setup();using var owned=f;var cut=Choose(source);cut.Find("[data-testid=type-copy-kind]").Change("Daily");cut.Find("[data-testid=type-copy-prepare]").Click();Assert.Contains("explicit new Daily start",cut.Markup);Assert.Empty(f.Task.Client.PreparationIds);cut.Find("[data-testid=type-copy-start]").Change("2026-11-03");cut.Find("[data-testid=type-copy-zone]").Change("Missing/Zone");cut.Find("[data-testid=type-copy-prepare]").Click();Assert.Contains("available time zone",cut.Markup);Assert.Empty(f.Task.Client.PreparationIds);Save("type-copy-invalid-rule",cut.Markup,"explicit-rule-validation-error");
    }
    [Fact]public async Task Uncertain_acceptance_and_preparation_recover_only_the_original_identity()
    {
        var(f,source)=await Setup();using var owned=f;f.Task.Client.LosePreparation=true;var cut=Choose(source);Prepare(cut,CompanionTaskKind.Habit);Assert.True(f.Task.Controller.PreparationUnknown);Save("type-copy-prepare-unknown",cut.Markup,"unknown-original-preparation");cut.Find("[data-testid=type-copy-retry]").Click();cut.WaitForAssertion(()=>Assert.NotNull(f.Task.Controller.Preview));var id=f.Task.Controller.Preview!.PreparedCommandId;Assert.Single(f.Task.Client.PreparationIds.Distinct());f.Task.Client.LoseAcceptance=true;cut.Find("[data-testid=type-copy-ack]").Change(true);cut.Find("[data-testid=type-copy-confirm]").Click();cut.WaitForAssertion(()=>Assert.True(f.Task.Controller.AcceptanceUnknown));Assert.Empty(cut.FindAll("[data-testid=type-copy-kind]"));Save("type-copy-unknown",cut.Markup,"acceptance-unknown-original-receipt-required");
        var actual=WorkspaceTaskController.Receipt(f.Task.Client.State.Commands.Single(),Guid.NewGuid());f.Task.Client.ReceiptReadAction=_=>Task.FromResult(new Habitica.Application.Workspace.WorkspaceTaskResponse<Habitica.Application.Workspace.WorkspaceMutationReceipt>(true,actual with{CopyLineage=actual.CopyLineage! with{SourceSnapshot=actual.CopyLineage!.SourceSnapshot with{Notes="Forged before fields"}}},"Synthetic untrusted receipt"));await f.Todo.CheckOriginalAsync();Assert.True(f.Task.Controller.AcceptanceUnknown);Assert.Null(f.Task.Controller.LastReceipt);f.Task.Client.ReceiptReadAction=null;
        cut.Find("[data-testid=type-copy-recover]").Click();cut.WaitForAssertion(()=>Assert.NotNull(f.Task.Controller.LastReceipt));Assert.Equal(id,f.Task.Controller.LastReceipt!.CommandId);Assert.Single(f.Task.Client.AcceptedIds);Assert.All(f.Task.Client.ReceiptReads,read=>Assert.Equal(id,read));Assert.Equal(2,f.Task.Client.State.Document.Tasks.Count);
    }
    [Fact]public async Task Paging_and_account_switch_preserve_exact_selection_and_clear_private_review()
    {
        var(f,source)=await Setup(extra:21,longName:true);using var owned=f;var cut=Render<TaskTypeCopyPanel>();Assert.Equal(20,cut.FindAll("[data-testid^=type-copy-source-]").Count);cut.Find("[data-testid=type-copy-next]").Click();Assert.Equal(2,cut.FindAll("[data-testid^=type-copy-source-]").Count);cut.Find($"[data-testid=type-copy-source-{source.Id:D}]").Click();Save("type-copy-long-editor",cut.Markup,"long-title-source-selection");Prepare(cut,CompanionTaskKind.Habit);Save("type-copy-long",cut.Markup,"long-private-title-review");f.Task.Session.SetState(f.Task.Session.State with{UserId=Guid.NewGuid().ToString("D")});cut.WaitForAssertion(()=>Assert.Empty(cut.FindAll("[data-testid=type-copy-review]")));Assert.DoesNotContain(source.Text,cut.Markup);Assert.DoesNotContain(source.Notes!,cut.Markup);Assert.Empty(f.Task.Client.AcceptedIds);Save("type-copy-account",cut.Markup,"account-switch-clears-private-data");
    }
    [Fact]public async Task Browser_copy_uses_atomic_storage_and_freezes_a_stale_source_selection()
    {
        var(f,source)=await Setup(cloud:false);using var owned=f;var cut=Choose(source);Prepare(cut,CompanionTaskKind.Habit);cut.Find("[data-testid=type-copy-ack]").Change(true);cut.Find("[data-testid=type-copy-confirm]").Click();cut.WaitForAssertion(()=>Assert.NotNull(f.Task.Controller.LastReceipt));Assert.NotNull(f.Task.Controller.LastReceipt!.CopyLineage);Assert.Empty(f.Task.Client.AcceptedIds);Assert.Equal(2,f.Todo.Snapshot!.Document.Tasks.Count);Assert.Empty(cut.FindAll("[data-testid=type-copy-kind]"));Save("type-copy-browser",cut.Markup,"browser-atomic-receipt");
    }
}
